] satisfies ListInputColumn<FamilyMember>[];

<ListInput
  label="Family member declaration"
  itemName="family member"
  value={members}
  onChange={setMembers}
  getItemKey={member => member.id}
  createItem={() => ({
    id: crypto.randomUUID(),
    fullName: '',
    relationship: '',
    dateOfBirth: undefined,
  })}
  columns={columns}
  isRequired
/>
```

## Theming

| Component class | Preferred data attributes | Props | States |
|-----------------|---------------------------|-------|--------|
| `astryx-list-input` | `data-state`, `data-reorderable` | state, reorderable | - |

Override in defineTheme:
```ts
components: {
  'list-input': {
    base: { /* CSS properties */ },
    'state:value': { /* variant-specific */ },
  },
}
```
